import json, math
V=6
kappa,eps,Pmax=1e-3,1e-4,16
def run(seq,rho):
    a=[0.0]*V
    C={}
    prev=None
    for w in seq:
        a[w]=1.0
        if prev is not None and prev<3 and w>=3 and rho>kappa:
            i,j=prev,w
            xi=a[i]-sum(c for (p,q),c in C.items() if p==i)
            yj=a[j]-sum(c for (p,q),c in C.items() if q==j)
            col=sum(c for (p,q),c in C.items() if q==j and p!=i)
            row=sum(c for (p,q),c in C.items() if p==i and q!=j)
            cij=C.get((i,j),0.0)
            new={}
            for (p,q),c in C.items():
                if (p,q)==(i,j): continue
                if q==j: new[(p,q)]=c*(1-rho*xi)
                elif p==i: new[(p,q)]=c*(1-rho*yj)
                else: new[(p,q)]=c
            new[(i,j)]=cij+rho*(xi*yj+xi*col+yj*row)
            new={k:c for k,c in new.items() if c>=eps}
            while len(new)>Pmax:
                del new[min(new,key=lambda z:new[z])]
            C=new
        prev=w
    return C
def cr(C):
    cells=[(0,3),(1,4),(0,4),(1,3)]
    if any(c not in C or C[c]<=0 for c in cells): return None
    return C[(0,3)]*C[(1,4)]/(C[(0,4)]*C[(1,3)])
pre=[0,3,1,4,0,4,1,3]
res={}
bad=False
for rho in (0.9,0.95,0.99):
    cA=cr(run(pre+[2,3,0,3],rho))
    cB=cr(run(pre+[2,5,0,3],rho))
    if cA is None or cB is None:
        res[rho]='undefined'; bad=True
    else:
        d=abs(math.log(cA/cB)); res[rho]=round(d,4)
        if d<0.2: bad=True
print(json.dumps({"disproved":bool(bad),"detail":str(res)}))
